export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  var scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.16, 0.15, 0.17);

  const camera = new BABYLON.ArcRotateCamera("camera1", 2.28, 1.317, 20, new BABYLON.Vector3(0, 3.6, 0), scene);
  camera.attachControl(canvas, true);
  camera.wheelPrecision = 50;

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);

  const customMaterials = [];

  BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "human_house.glb").then((result) => {
    const rootMesh = result.meshes[0];

    let fresnelColor = new BABYLON.Color3(0.92, 1, 0.2);
    let fresnelStrength = 0.01;

    const fresnelParams = {
      color: [fresnelColor.r * 255, fresnelColor.g * 255, fresnelColor.b * 255],
      strength: fresnelStrength,
    };

    rootMesh.getChildMeshes().forEach((mesh) => {
      if (mesh.material && mesh.material instanceof BABYLON.PBRMaterial) {
        const original = mesh.material;
        const customMaterial = new BABYLON.CustomMaterial("customMaterial", scene);
        customMaterial.diffuseTexture = original.albedoTexture;
        customMaterial.diffuseColor = original.albedoColor;
        customMaterial.emissiveColor = BABYLON.Color3.White();
        customMaterial.bumpTexture = original.bumpTexture;

        customMaterial.AddUniform(
          "uFresnelColor",
          "vec3",
          new BABYLON.Vector3(fresnelParams.color[0], fresnelParams.color[1], fresnelParams.color[2])
        );
        customMaterial.AddUniform("uFresnelStrength", "float", fresnelParams.strength);

        customMaterial.Fragment_Before_FragColor(`
                    float fresnelTerm = pow(1.0 - dot(viewDirectionW, vNormalW), 3.0);
                    fresnelTerm = clamp(fresnelTerm * uFresnelStrength, 0.0, 1.0);
                    color.rgb = mix(color.rgb, uFresnelColor, fresnelTerm);
                `);

        customMaterial.onBind = (mesh) => {
          const effect = customMaterial.getEffect();
          if (effect) {
            effect.setFloat("uFresnelStrength", fresnelParams.strength);
            effect.setVector3("uFresnelColor", new BABYLON.Vector3(fresnelParams.color[0], fresnelParams.color[1], fresnelParams.color[2]));
          }
        };

        mesh.material = customMaterial;
        customMaterials.push(customMaterial);
      }
    });

    const advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

    const panel = new BABYLON.GUI.StackPanel();
    panel.width = "220px";
    panel.isVertical = true;
    panel.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_RIGHT;
    panel.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;
    panel.top = "-50px";
    panel.paddingRight = "10px";
    panel.isPointerBlocker = true;
    advancedTexture.addControl(panel);

    // Color Picker Label
    const colorLabel = new BABYLON.GUI.TextBlock();
    colorLabel.text = "Fresnel Color";
    colorLabel.height = "30px";
    colorLabel.color = "white";
    panel.addControl(colorLabel);

    // Color Picker
    const colorPicker = new BABYLON.GUI.ColorPicker();
    colorPicker.value = new BABYLON.Color3(fresnelParams.color[0], fresnelParams.color[1], fresnelParams.color[2]);
    colorPicker.height = "150px";
    colorPicker.width = "150px";
    colorPicker.onValueChangedObservable.add(function (value) {
      fresnelColor = value;
      fresnelParams.color = [fresnelColor.r * 255, fresnelColor.g * 255, fresnelColor.b * 255];
    });
    panel.addControl(colorPicker);

    // Strength Slider Label
    const sliderLabel = new BABYLON.GUI.TextBlock();
    sliderLabel.text = "Strength";
    sliderLabel.height = "30px";
    sliderLabel.color = "white";
    panel.addControl(sliderLabel);

    // Strength Slider
    const slider = new BABYLON.GUI.Slider();
    slider.minimum = 0.0;
    slider.maximum = 0.2;
    slider.value = fresnelParams.strength;
    slider.height = "20px";
    slider.width = "180px";
    slider.step = 0.001;
    slider.onValueChangedObservable.add(function (value) {
      fresnelParams.strength = value;
    });
    panel.addControl(slider);
  });

  return scene;
}
